function singularize(s) {
  if (/ies$/.test(s)) return s.replace(/ies$/, "y");
  if (/ses$/.test(s)) return s.replace(/es$/, "");
  if (/s$/.test(s) && !/ss$/.test(s)) return s.replace(/s$/, "");
  return s;
}
function genConfig(name) {
  const noun = singularize(name);
  return {
    title: name,
    subtitle: `Manage your organization's ${name.toLowerCase()}.`,
    cta: `Add ${noun}`,
    noun,
    cols: [{
      key: "name",
      label: "Name"
    }, {
      key: "code",
      label: "Reference"
    }],
    fields: [{
      key: "name",
      label: "Name",
      placeholder: `Enter ${noun.toLowerCase()} name`
    }, {
      key: "code",
      label: "Reference",
      placeholder: "Enter reference",
      optional: true
    }, {
      key: "description",
      label: "Description",
      type: "textarea",
      placeholder: "Enter description",
      full: true,
      optional: true
    }]
  };
}
Object.assign(window, {
  CONFIGS,
  SEED,
  genConfig,
  singularize
});
