const WF_PHASES = ["Review", "Approval", "Processing", "Closure"];
const WF_INDEX = WF_STATUS.reduce((a, s, i) => (a[s.key] = i, a), {});
const wfVariant = status => (WF_STATUS[WF_INDEX[status]] || {}).variant || "default";
